"""Shared helpers for talking to FT2 and analysing renders."""
import json, subprocess, wave, numpy as np, os

SR = 44100
FT2_ROOT = 8363.0

def call(calls, tag=None):
    if tag is None:
        p = '/workspace/build/_batch.json'
    else:
        p = f'/workspace/build/{tag}.json'
    open(p, 'w').write(json.dumps(calls))
    r = subprocess.run(['ft2', 'batch', p], capture_output=True, text=True)
    if r.returncode != 0:
        print("ERR", tag, r.stdout[-2000:], r.stderr[-800:])
        raise SystemExit(1)
    return r.stdout

def load(path='/workspace/build/out.wav'):
    w = wave.open(path, 'rb'); sr = w.getframerate(); n = w.getnframes()
    a = np.frombuffer(w.readframes(n), dtype=np.int16).reshape(-1, 2).astype(np.float64) / 32768
    w.close()
    return sr, a

def rowtime(bpm=150, speed=6):
    return speed / (bpm * 24.0 / 60.0)

def rms(x):
    return float(np.sqrt((x ** 2).mean())) if len(x) else 0.0

def peakfreq(seg, sr=44100, n=3, lo=25):
    if len(seg) < 32:
        return []
    s = seg * np.hanning(len(seg))
    sp = np.abs(np.fft.rfft(s)); f = np.fft.rfftfreq(len(s), 1 / sr)
    order = np.argsort(sp)[::-1]; got = []
    for j in order:
        if f[j] < lo or sp[j] < 0.05 * sp[order[0]]: continue
        if any(abs(f[j] - g) < max(6, g * 0.03) for g in got): continue
        # parabolic refine
        if 0 < j < len(sp) - 1:
            y0, y1, y2 = sp[j - 1], sp[j], sp[j + 1]
            den = (y0 - 2 * y1 + y2)
            d = 0.5 * (y0 - y2) / den if den != 0 else 0.0
            got.append((j + d) * (f[1] - f[0]))
        else:
            got.append(f[j])
        if len(got) >= n: break
    return np.round(sorted(got), 2)

def write_wav(path, x, sr=44100, bits=16):
    x = np.clip(x, -1.0, 1.0)
    y = (x * 32767).astype(np.int16)
    w = wave.open(path, 'wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(sr)
    w.writeframes(y.tobytes()); w.close()
    return len(y)
