"""Sample synthesis in the FT2 'frame' domain (8363 frames/sec == C-4 playback rate)."""
import numpy as np, wave, math
FR = 8363.0   # frames per second at note 49 with relative_note 0

def content_freq(period_frames):
    return FR / period_frames

def freq_at(note, content_f, rel=0):
    return content_f * 2 ** ((note + rel - 49) / 12.0)

def period_for(target_hz_at_C4):
    return FR / target_hz_at_C4

def loop_table(target_hz_at_C4, cycles=128):
    """Return (L, actual_hz) for an integer loop length holding `cycles` periods."""
    P = FR / target_hz_at_C4
    L = int(round(cycles * P))
    return L, cycles * FR / L

def w16(path, x, sr=44100):
    x = np.clip(np.asarray(x, dtype=np.float64), -1.0, 1.0)
    y = (x * 32767).astype(np.int16)
    w = wave.open(path, 'wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(sr)
    w.writeframes(y.tobytes()); w.close()
    return len(y)

def phase(n, freq_fn=None, f0=0.0):
    """cumulative phase for possibly time-varying freq (freq_fn(t_frames)->hz)."""
    i = np.arange(n)
    if freq_fn is None:
        return 2 * np.pi * f0 * i / FR
    f = freq_fn(i / FR)
    return 2 * np.pi * np.cumsum(f) / FR

def saw(ph):
    p = (ph / (2 * np.pi)) % 1.0
    return 2 * p - 1

def square(ph, duty=0.5):
    p = (ph / (2 * np.pi)) % 1.0
    return np.where(p < duty, 1.0, -1.0)

def tri(ph):
    p = (ph / (2 * np.pi)) % 1.0
    return 4 * np.abs(p - 0.5) - 1

def harm_saw(ph, nh=24, roll=1.0):
    x = np.zeros(len(ph))
    for k in range(1, nh + 1):
        x += np.sin(k * ph) / (k ** roll)
    return x / max(1e-9, np.abs(x).max())

def harm_square(ph, nh=24):
    x = np.zeros(len(ph))
    for k in range(1, nh, 2):
        x += np.sin(k * ph) / k
    return x / max(1e-9, np.abs(x).max())

def noise(n, seed=1234):
    rng = np.random.default_rng(seed)
    return rng.uniform(-1, 1, n)

def onepole_hp(x, a):
    y = np.zeros_like(x); prev = 0.0; prevx = 0.0
    for i in range(len(x)):
        prev = a * (prev + x[i] - prevx)
        prevx = x[i]; y[i] = prev
    return y

def decay(n, t60):
    """exponential decay to ~0 over t60 seconds (frame domain)."""
    i = np.arange(n)
    return np.exp(-6.9 * (i / FR) / max(1e-9, t60))

def attack_hold(n, atk, sus=1.0, t60=None):
    i = np.arange(n) / FR
    e = np.minimum(1.0, i / max(atk, 1e-6))
    if t60:
        e = e * np.exp(-6.9 * i / t60)
    return e * sus
